import os, json, textwrap, sys, subprocess, pathlib, shutil, filecmp, py_compile

TARGET = os.environ["TARGET_DIR"]
# 1. Modify api_keys_required in camel/utils/commons.py
commons_path = pathlib.Path(TARGET) / "camel/utils/commons.py"
src = commons_path.read_text()
old_logic = """def api_keys_required(*required_keys: str) -> Callable[[F], F]:
    r\"\"\"A decorator to check if the required API keys are
    presented in the environment variables or as an instance attribute.

    Args:
        required_keys (str): The required API keys to be checked.

    Returns:
        Callable[[F], F]: The original function with the added check
            for required API keys.

    Raises:
        ValueError: If any of the required API keys are missing in the
            environment variables and the instance attribute.

    Example:
        ::

            @api_keys_required('API_KEY_1', 'API_KEY_2')
            def some_api_function():
                # Function implementation...
    \"\"\"

    def decorator(func: F) -> F:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            missing_environment_keys = [
                k for k in required_keys if k not in os.environ
            ]
            if (
                not (args and getattr(args[0], '_api_key', None))
                and missing_environment_keys
            ):
                raise ValueError(
                    f\"Missing API keys: {', '.join(missing_environment_keys)}\"
                )
            return func(*args, **kwargs)

        return cast(F, wrapper)

    return decorator
"""
new_logic = """def api_keys_required(*required_keys: str) -> Callable[[F], F]:
    r\"\"\"A decorator to check if the required API keys are
    presented in the environment variables, as an instance attribute,
    or passed as keyword arguments.

    Args:
        required_keys (str): The required API keys to be checked.

    Returns:
        Callable[[F], F]: The original function with the added check
            for required API keys.

    Raises:
        ValueError: If any of the required API keys are missing after
            checking environment variables, instance attributes, and
            keyword arguments.

    Example:
        ::

            @api_keys_required('API_KEY_1', 'API_KEY_2')
            def some_api_function():
                # Function implementation...
    \"\"\"

    def decorator(func: F) -> F:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            # Resolve possible instance (self) if method is bound
            instance = args[0] if args else None

            missing_keys = []
            for key in required_keys:
                # 1. Environment variable
                if key in os.environ:
                    continue
                # 2. Instance attribute (case‑insensitive)
                if instance is not None:
                    if hasattr(instance, key):
                        continue
                    if hasattr(instance, key.lower()):
                        continue
                    # Support dict‑like objects
                    if isinstance(instance, dict) and key in instance:
                        continue
                # 3. Keyword argument
                if key in kwargs:
                    continue
                missing_keys.append(key)

            if missing_keys:
                raise ValueError(
                    f\"Missing API keys: {', '.join(missing_keys)}\"
                )
            return func(*args, **kwargs)

        return cast(F, wrapper)

    return decorator  # ENHANCED_V1: extended lookup to instance attrs and kwargs
"""
if old_logic in src:
    src = src.replace(old_logic, new_logic)
    commons_path.write_text(src)
else:
    # fallback: replace the function definition block more generically
    import re
    pattern = r'def api_keys_required\\(\\*required_keys: str\\) -> Callable\\[\\[F\\], F\\]:[\\s\\S]*?return decorator'
    src = re.sub(pattern, new_logic, src, count=1)
    commons_path.write_text(src)

# 2. Add new tests to test/utils/test_commons.py
test_path = pathlib.Path(TARGET) / "test/utils/test_commons.py"
test_src = test_path.read_text()
new_tests = '''
def test_api_keys_required_attribute_match(setup_env_vars):
    # Ensure env does not provide the key
    os.environ.clear()

    class MockClass:
        def __init__(self):
            self.API_KEY_1 = "value"

        @api_keys_required('API_KEY_1')
        def method(self):
            return True

    instance = MockClass()
    assert instance.method() is True  # ENHANCED_V1: attribute match


def test_api_keys_required_lowercase_attribute(setup_env_vars):
    os.environ.clear()

    class MockClass:
        def __init__(self):
            self.api_key_1 = "value"

        @api_keys_required('API_KEY_1')
        def method(self):
            return True

    instance = MockClass()
    assert instance.method() is True  # ENHANCED_V1: lowercase attribute match


def test_api_keys_required_keyword_argument(setup_env_vars):
    os.environ.clear()

    @api_keys_required('API_KEY_1')
    def func(**kwargs):
        return True

    assert func(API_KEY_1='value') is True  # ENHANCED_V1: kwarg match
'''
if new_tests.strip() not in test_src:
    # Append new tests at end of file
    test_path.write_text(test_src + "\n" + new_tests)

# 3. Verify syntax of modified python files
for root, dirs, files in os.walk(TARGET):
    for f in files:
        if f.endswith('.py'):
            full = os.path.join(root, f)
            try:
                py_compile.compile(full, doraise=True)
            except Exception as e:
                print(f"Syntax error in {full}: {e}", file=sys.stderr)
                sys.exit(1)

print("All modified files compiled successfully.")
